insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_recommend_9','recommend','verb','to advise someone to do something, or to say that someone or something is good and suitable','[{"senseId":"recommend_9_1","meaning":"to advise someone to do something, or to say that someone or something is good and suitable","acceptedParaphrases":["advise","say something is good"],"masteryContexts":[{"contextId":"u9_41_recommend_9_meaning","text":"The experts recommend that schools teach students how to check online information.","meaning":"to advise that something should be done","wrongMeanings":["to warn against something","to complain about something","to forbid something"]},{"contextId":"u9_41_recommend_9_paraphrase","text":"Can you recommend a good book about communication skills?","meaning":"to say that something is good and suitable","wrongMeanings":["to say that something is too expensive","to say that something is boring","to say that something is dangerous"]}],"situationDistractors":["A sign warned visitors to stay away from the cliff edge.","A customer complained that the headphones broke after a day.","A boy kept the name of the restaurant secret from his friends.","A review warned readers to avoid the restaurant.","A customer complained that the phone was too slow.","A boy kept the name of his favourite café to himself."],"gapDistractors":[{"contextId":"u9_41_recommend_9_gap_1","answer":"recommend","wrong":["survive","ban","launch"]},{"contextId":"u9_41_recommend_9_gap_2","answer":"recommend","wrong":["survive","ban","differentiate"]},{"contextId":"u9_41_recommend_9_gap_3","answer":"recommend","wrong":["survive","launch","differentiate"]}],"spellingErrors":["recomend","reccomend","recommed","recomand","recommand","reccommend"],"wordFamilyForms":[{"form":"recommend","partOfSpeech":"verb","example":"Most reviewers recommend this app for learning languages.","pedagogicallyUseful":true},{"form":"recommendation","partOfSpeech":"noun","example":"I bought the book on my teacher’s recommendation.","pedagogicallyUseful":true,"altExample":"The doctor’s recommendation was to rest for a week."},{"form":"recommended","partOfSpeech":"adjective","example":"The recommended screen time for young children is under an hour.","pedagogicallyUseful":true,"altExample":"Follow the recommended steps to reset your password."}],"masteryPassages":[{"passageId":"u9_41_recommend_9_passage_1","contextId":"u9_41_recommend_9_gap_1","text":"The film got excellent reviews. Every critic I read would ____ it to anyone who enjoys science fiction.","answer":"recommend"},{"passageId":"u9_41_recommend_9_passage_2","contextId":"u9_41_recommend_9_gap_2","text":"Staring at a screen for hours can hurt your eyes. Eye doctors ____ that you take a short break every twenty minutes.","answer":"recommend"}],"contextDependentParaphrases":[],"wrongParaphrases":["warn against","complain about","keep secret"],"misleadingDistractors":["to warn people to avoid something","to complain about poor quality","to keep information to yourself"],"teacherNote":"Reporting verb: to advise or to say something is good (recommend + -ing; recommend that + clause; recommend something to someone). Common error: *recommend someone to do (not standard in this pattern for learners). Unit 9 treats it as a reporting verb; Unit 1 taught it for free-time choices. The noun recommendation is taught in the Word Family pathway."}]'::jsonb,'["recommendation","recommended"]'::jsonb,'["recommend doing something","strongly recommend","recommend something to someone"]'::jsonb,'live'),
('vocab_solution_9','solution','noun','a way of dealing with a problem or difficult situation successfully','[{"senseId":"solution_9_1","meaning":"a way of dealing with a problem or difficult situation successfully","acceptedParaphrases":["answer to a problem","way to fix a problem"],"masteryContexts":[{"contextId":"u9_42_solution_9_meaning","text":"The report ends by suggesting one practical solution to the problem of noise in the library.","meaning":"a way of dealing with a difficulty","wrongMeanings":["a description of how serious a problem is","a list of the causes of a problem","a question about a problem"]},{"contextId":"u9_42_solution_9_paraphrase","text":"The engineers finally found a solution, and the app stopped crashing.","meaning":"something that solves a difficulty","wrongMeanings":["a reason why something went wrong","a person who reports a problem","a test that shows a problem"]}],"situationDistractors":["A scientist explained why the river had become polluted.","A philosopher asked a question that nobody could answer.","A journalist described how serious the traffic problem was.","A report described how serious the flooding was.","A scientist explained what caused the illness.","A student asked a question that nobody could answer."],"gapDistractors":[{"contextId":"u9_42_solution_9_gap_1","answer":"solution","wrong":["frustration","perception","workforce"]},{"contextId":"u9_42_solution_9_gap_2","answer":"solution","wrong":["frustration","perception","workforce"]},{"contextId":"u9_42_solution_9_gap_3","answer":"solution","wrong":["frustration","workforce","perception"]}],"spellingErrors":["solusion","solutoin","soloution","soluton","sollution","solucion"],"wordFamilyForms":[{"form":"solution","partOfSpeech":"noun","example":"The class found a simple solution to the noise problem.","pedagogicallyUseful":true},{"form":"solve","partOfSpeech":"verb","example":"It took the technicians two days to solve the problem.","pedagogicallyUseful":true,"altExample":"Working together, the class managed to solve the puzzle."},{"form":"unsolved","partOfSpeech":"adjective","example":"The mystery of the missing files remained unsolved.","pedagogicallyUseful":true,"altExample":"Several technical problems are still unsolved."}],"masteryPassages":[{"passageId":"u9_42_solution_9_passage_1","contextId":"u9_42_solution_9_gap_1","text":"The library was always too noisy for studying. The ____ was to create a separate silent room upstairs.","answer":"solution"},{"passageId":"u9_42_solution_9_passage_2","contextId":"u9_42_solution_9_gap_2","text":"Fake news is a serious problem, and there is no simple ____. Teaching students to check sources is one way to help.","answer":"solution"}],"contextDependentParaphrases":[],"wrongParaphrases":["cause of a problem","description of a problem","question with no answer"],"misleadingDistractors":["the cause of a problem","a question that has no answer","a description of how bad a problem is"],"teacherNote":"Noun: a way of solving or dealing with a problem (a solution to/for a problem, find a solution, a practical solution). Note the preposition \"to\". Unit 9 uses it in problem-solution writing and reports; Unit 1 taught it in a different topic. The verb solve and the adjective solvable are related; the Word Family pathway teaches solve."}]'::jsonb,'["solve","unsolved"]'::jsonb,'["a solution to","find a solution","a practical solution"]'::jsonb,'live'),
('vocab_introduction','introduction','noun','the first part of a piece of writing or a talk, which explains what it is about','[{"senseId":"introduction_1","meaning":"the first part of a piece of writing or a talk, which explains what it is about","acceptedParaphrases":["opening section","beginning that explains the topic"],"masteryContexts":[{"contextId":"u9_43_introduction_meaning","text":"In the introduction to your report, state its purpose and who it is for.","meaning":"the opening part of a piece of writing","wrongMeanings":["the closing part of a piece of writing","the list of sources at the end","the title on the cover"]},{"contextId":"u9_43_introduction_paraphrase","text":"The speaker’s introduction was so funny that the audience was immediately interested.","meaning":"the beginning of a talk","wrongMeanings":["the end of a talk","the questions after a talk","the slides used in a talk"]}],"situationDistractors":["A student summed up her main points in the final paragraph.","A writer listed all the books he had used at the end of the report.","A designer printed the title in large letters on the cover.","A writer added a list of sources at the end of her book.","A student summed up her ideas in the final paragraph.","A speaker thanked the audience as she finished."],"gapDistractors":[{"contextId":"u9_43_introduction_gap_1","answer":"introduction","wrong":["frustration","workforce","perception"]},{"contextId":"u9_43_introduction_gap_2","answer":"introduction","wrong":["frustration","workforce","accuracy"]},{"contextId":"u9_43_introduction_gap_3","answer":"introduction","wrong":["frustration","workforce","accuracy"]}],"spellingErrors":["introdution","intruduction","introducsion","introducton","introdcution","intorduction"],"wordFamilyForms":[{"form":"introduction","partOfSpeech":"noun","example":"A good introduction tells the reader what the essay is about.","pedagogicallyUseful":true},{"form":"introduce","partOfSpeech":"verb","example":"Let me introduce our guest speaker for today.","pedagogicallyUseful":true,"altExample":"The school plans to introduce a new phone policy next term."},{"form":"introductory","partOfSpeech":"adjective","example":"The course begins with an introductory lesson on research skills.","pedagogicallyUseful":true,"altExample":"An introductory video explains how to use the platform."}],"masteryPassages":[{"passageId":"u9_43_introduction_passage_1","contextId":"u9_43_introduction_gap_1","text":"Readers decide very quickly whether to continue reading. That is why your ____ should be short, clear and interesting.","answer":"introduction"},{"passageId":"u9_43_introduction_passage_2","contextId":"u9_43_introduction_gap_2","text":"The book’s ____ explains why the author decided to write it. The main chapters then tell the story of her life.","answer":"introduction"}],"contextDependentParaphrases":[],"wrongParaphrases":["closing summary","list of sources","cover title"],"misleadingDistractors":["the final part that sums up the main points","a list of books used for research","the title written on the cover"],"teacherNote":"Noun: the first part of a text or talk that explains its topic and purpose (in the introduction, write an introduction). Key for Paper 2 report and article structure. Opposite in structure: conclusion. Other senses (introducing people; bringing something in for the first time) exist but are not the focus. The verb introduce is taught in the Word Family pathway."}]'::jsonb,'["introduce","introductory"]'::jsonb,'["in the introduction","a short introduction","write an introduction"]'::jsonb,'live'),
('vocab_conclusion','conclusion','noun','the final part of a piece of writing or a talk, which sums up the main points','[{"senseId":"conclusion_1","meaning":"the final part of a piece of writing or a talk, which sums up the main points","acceptedParaphrases":["ending","final summary"],"masteryContexts":[{"contextId":"u9_44_conclusion_meaning","text":"A strong conclusion reminds the reader of your main points without repeating them word for word.","meaning":"the final part of a piece of writing","wrongMeanings":["the opening part of a piece of writing","the title of a piece of writing","the longest part of a piece of writing"]},{"contextId":"u9_44_conclusion_paraphrase","text":"After reading all the evidence, the team came to the conclusion that the app was not safe.","meaning":"a decision reached after thinking","wrongMeanings":["a question asked before deciding","a guess made without evidence","a disagreement between experts"]}],"situationDistractors":["A student wrote the opening sentence of her story.","A member of the audience asked the speaker a question.","A journalist chose the headline for an article.","A writer planned the first paragraph of her essay.","A speaker said \"Good morning\" to begin his talk.","A designer chose a title for the report."],"gapDistractors":[{"contextId":"u9_44_conclusion_gap_1","answer":"conclusion","wrong":["frustration","workforce","perception"]},{"contextId":"u9_44_conclusion_gap_2","answer":"conclusion","wrong":["frustration","workforce","community"]},{"contextId":"u9_44_conclusion_gap_3","answer":"conclusion","wrong":["frustration","workforce","community"]}],"spellingErrors":["conclution","conclusoin","consclusion","conclussion","conclsion","conclushion"],"wordFamilyForms":[{"form":"conclusion","partOfSpeech":"noun","example":"Summarise your main points in the conclusion.","pedagogicallyUseful":true},{"form":"conclude","partOfSpeech":"verb","example":"Most readers will conclude that the writer is right.","pedagogicallyUseful":true,"altExample":"Scientists conclude that the new method is safer."},{"form":"conclusive","partOfSpeech":"adjective","example":"There is no conclusive evidence that the new app improves grades.","pedagogicallyUseful":true,"altExample":"The test results were not conclusive, so more tests are needed."}],"masteryPassages":[{"passageId":"u9_44_conclusion_passage_1","contextId":"u9_44_conclusion_gap_1","text":"The writer presents both sides of the argument in the main paragraphs. She gives her own opinion in the ____ at the end.","answer":"conclusion"},{"passageId":"u9_44_conclusion_passage_2","contextId":"u9_44_conclusion_gap_2","text":"The scientists studied the data for months. They finally came to the ____ that the new medicine was safe.","answer":"conclusion"}],"contextDependentParaphrases":[],"wrongParaphrases":["opening paragraph","audience question","report title"],"misleadingDistractors":["the first paragraph of an essay","a question asked by the audience","the title of a report"],"teacherNote":"Noun: (1) the final part of a text or talk that sums up the main points (in conclusion, write a conclusion); (2) a decision reached after thinking (come to/reach a conclusion). Both are useful in Paper 2. Opposite in structure: introduction. The verb conclude is taught in the Word Family pathway."}]'::jsonb,'["conclude","conclusive"]'::jsonb,'["in conclusion","reach a conclusion","a strong conclusion"]'::jsonb,'live'),
('vocab_audience','audience','noun','the people who watch, listen to or read something','[{"senseId":"audience_1","meaning":"the people who watch, listen to or read something","acceptedParaphrases":["viewers or listeners","readers"],"masteryContexts":[{"contextId":"u9_45_audience_meaning","text":"The article was written for a teenage audience, so it uses simple language and examples from school life.","meaning":"the people who read something","wrongMeanings":["the people who write something","the people who print something","the people who sell something"]},{"contextId":"u9_45_audience_paraphrase","text":"The audience laughed at the speaker’s jokes and asked many questions afterwards.","meaning":"the people listening to a talk","wrongMeanings":["the people organising a talk","the people recording a talk","the people paying for a talk"]}],"situationDistractors":["A writer spent the morning finishing her speech.","A caretaker set up chairs in the school hall.","A teacher chose climate change as the topic of the talk.","A writer finished the last page of her novel alone at home.","A technician fixed the microphone before the show.","An organiser booked the hall for a concert."],"gapDistractors":[{"contextId":"u9_45_audience_gap_1","answer":"audience","wrong":["accuracy","frustration","perception"]},{"contextId":"u9_45_audience_gap_2","answer":"audience","wrong":["accuracy","frustration","perception"]},{"contextId":"u9_45_audience_gap_3","answer":"audience","wrong":["accuracy","frustration","perception"]}],"spellingErrors":["audiance","audence","audiense","adience","audeince","awdience"],"masteryPassages":[{"passageId":"u9_45_audience_passage_1","contextId":"u9_45_audience_gap_1","text":"The magazine is read mainly by teenagers. Its writers use simple language and examples that suit this ____.","answer":"audience"},{"passageId":"u9_45_audience_passage_2","contextId":"u9_45_audience_gap_2","text":"The speaker made eye contact, told jokes and asked questions. By the end, the whole ____ was clapping.","answer":"audience"}],"contextDependentParaphrases":[],"wrongParaphrases":["speechwriters","venue staff","topics"],"misleadingDistractors":["the person who writes a speech","the room where a talk takes place","the topic that a talk is about"],"teacherNote":"Noun (countable, collective): the people who watch, listen to or read something (a large audience, the target audience, write for an audience). Key for Paper 2: audience and purpose decide the right register. Boundary: the audience is people, not the place. Word Families is not counted (audible/audition are not useful family members here)."}]'::jsonb,'[]'::jsonb,'["the target audience","a large audience","engage the audience"]'::jsonb,'live'),
('vocab_purpose','purpose','noun','the reason why something is done or made, or what it is intended to achieve','[{"senseId":"purpose_1","meaning":"the reason why something is done or made, or what it is intended to achieve","acceptedParaphrases":["aim","reason for doing something"],"masteryContexts":[{"contextId":"u9_46_purpose_meaning","text":"The main purpose of the campaign is to encourage students to talk face-to-face more often.","meaning":"the aim of an activity","wrongMeanings":["the cost of an activity","the location of an activity","the timing of an activity"]},{"contextId":"u9_46_purpose_paraphrase","text":"The writer’s purpose is to persuade readers to stop buying fast fashion.","meaning":"what a text is intended to achieve","wrongMeanings":["what a text accidentally shows","how long a text is","who wrote a text"]}],"situationDistractors":["By accident, the chemist discovered a new colour of paint.","The conference took place in a large hotel near the airport.","The article was read by thousands of people online.","A boy knocked over a glass by accident.","A meeting took place in the library.","Thousands of people read the article online."],"gapDistractors":[{"contextId":"u9_46_purpose_gap_1","answer":"purpose","wrong":["workforce","frustration","accuracy"]},{"contextId":"u9_46_purpose_gap_2","answer":"purpose","wrong":["workforce","frustration","accuracy"]},{"contextId":"u9_46_purpose_gap_3","answer":"purpose","wrong":["workforce","frustration","accuracy"]}],"spellingErrors":["porpose","purpuse","perpose","purpos","purpouse","purppose"],"masteryPassages":[{"passageId":"u9_46_purpose_passage_1","contextId":"u9_46_purpose_gap_1","text":"Before you begin writing, decide whether you want to inform, persuade or entertain. Knowing your ____ will help you choose the right style.","answer":"purpose"},{"passageId":"u9_46_purpose_passage_2","contextId":"u9_46_purpose_gap_2","text":"The ____ of the meeting was to plan the school trip. By the end, everyone knew what to do.","answer":"purpose"}],"contextDependentParaphrases":[],"wrongParaphrases":["accident","location","readership"],"misleadingDistractors":["the result that happens by accident","the place where something happens","the person who reads a text"],"teacherNote":"Noun: the reason for doing or making something, or what it is meant to achieve (the purpose of ..., for the purpose of ..., on purpose). Key for Paper 2: identify the purpose (inform, persuade, complain, describe) before writing. Boundary: \"on purpose\" means deliberately. The adjective purposeful is taught in the Word Family pathway."}]'::jsonb,'[]'::jsonb,'["the main purpose","the purpose of","on purpose"]'::jsonb,'live'),
('vocab_evaluate_9','evaluate','verb','to think carefully about something in order to judge its quality, value or importance','[{"senseId":"evaluate_9_1","meaning":"to think carefully about something in order to judge its quality, value or importance","acceptedParaphrases":["judge","assess"],"masteryContexts":[{"contextId":"u9_47_evaluate_9_meaning","text":"In the final paragraph, evaluate the advantages and disadvantages before giving your opinion.","meaning":"to judge strengths and weaknesses","wrongMeanings":["to list strengths and weaknesses without judging","to copy strengths and weaknesses from a source","to ignore strengths and weaknesses"]},{"contextId":"u9_47_evaluate_9_paraphrase","text":"The school asked parents to evaluate the new online learning platform.","meaning":"to judge the quality of something","wrongMeanings":["to pay for something","to advertise something","to install something"]}],"situationDistractors":["A student copied the paragraph word for word into his notebook.","A reporter described the event without giving any opinion.","A girl accepted the first website she found without checking it.","A student copied the answers from the board.","A reporter listed the facts without any opinion.","A girl believed the first website she found."],"gapDistractors":[{"contextId":"u9_47_evaluate_9_gap_1","answer":"evaluate","wrong":["survive","ban","launch"]},{"contextId":"u9_47_evaluate_9_gap_2","answer":"evaluate","wrong":["survive","ban","differentiate"]},{"contextId":"u9_47_evaluate_9_gap_3","answer":"evaluate","wrong":["survive","ban","launch"]}],"spellingErrors":["evalute","evaluat","evalaute","evaluete","evluate","evalueate"],"masteryPassages":[{"passageId":"u9_47_evaluate_9_passage_1","contextId":"u9_47_evaluate_9_gap_1","text":"Not every website is reliable. You should ____ each source carefully by checking who wrote it and when.","answer":"evaluate"},{"passageId":"u9_47_evaluate_9_passage_2","contextId":"u9_47_evaluate_9_gap_2","text":"The course has now finished. Students were asked to ____ the lessons, saying what worked well and what could be better.","answer":"evaluate"}],"contextDependentParaphrases":[],"wrongParaphrases":["copy","describe","ignore"],"misleadingDistractors":["to copy something without changing it","to describe something without giving an opinion","to ignore the strengths and weaknesses of something"],"teacherNote":"Verb: to judge the quality, value or importance of something after thinking carefully (evaluate the evidence, evaluate a source, evaluate whether ...). Unit 9 uses it for judging sources and arguments; earlier units used it in other topics. Boundary: describe only reports; evaluate judges. The noun evaluation is taught in the Word Family pathway."}]'::jsonb,'[]'::jsonb,'["evaluate the evidence","evaluate a source","critically evaluate"]'::jsonb,'live'),
('vocab_relevant_9','relevant','adjective','closely connected with the subject or situation being discussed','[{"senseId":"relevant_9_1","meaning":"closely connected with the subject or situation being discussed","acceptedParaphrases":["connected to the topic","related and useful"],"masteryContexts":[{"contextId":"u9_48_relevant_9_meaning","text":"In the summary task, choose the points that are relevant and leave out the examples.","meaning":"connected with the subject","wrongMeanings":["unconnected with the subject","longer than the subject","older than the subject"]},{"contextId":"u9_48_relevant_9_paraphrase","text":"The interviewer asked about my work experience that was relevant to the job.","meaning":"related to the situation being discussed","wrongMeanings":["unusual for the situation being discussed","dangerous in the situation being discussed","secret in the situation being discussed"]}],"situationDistractors":["A student included a story about his holiday in an essay about pollution.","A website still showed train times from ten years ago.","A report was so long that nobody finished reading it.","A student wrote about his pet in an essay about transport.","A website showed bus times from ten years ago.","A report was so long that nobody finished it."],"gapDistractors":[{"contextId":"u9_48_relevant_9_gap_1","answer":"relevant","wrong":["portable","tech-savvy","banned"]},{"contextId":"u9_48_relevant_9_gap_2","answer":"relevant","wrong":["portable","tech-savvy","banned"]},{"contextId":"u9_48_relevant_9_gap_3","answer":"relevant","wrong":["portable","tech-savvy","banned"]}],"spellingErrors":["relevent","relavant","revelant","relevat","relivant","relevaant"],"wordFamilyForms":[{"form":"relevant","partOfSpeech":"adjective","example":"Include only information that is relevant to the question.","pedagogicallyUseful":true},{"form":"relevance","partOfSpeech":"noun","example":"The examiner questioned the relevance of the final paragraph.","pedagogicallyUseful":true,"altExample":"Explain the relevance of each example to your argument."},{"form":"irrelevant","partOfSpeech":"adjective","example":"Most of the comments were irrelevant to the discussion.","pedagogicallyUseful":true,"altExample":"The judge said that the question was irrelevant."}],"masteryPassages":[{"passageId":"u9_48_relevant_9_passage_1","contextId":"u9_48_relevant_9_gap_1","text":"Your essay is about online safety. The paragraph about your holiday in Spain is not ____, so you should remove it.","answer":"relevant"},{"passageId":"u9_48_relevant_9_passage_2","contextId":"u9_48_relevant_9_gap_2","text":"The interviewer was not interested in my hobbies. She wanted to hear about experience that was ____ to the job.","answer":"relevant"}],"contextDependentParaphrases":[],"wrongParaphrases":["unconnected","out of date","too long"],"misleadingDistractors":["not connected to the topic at all","very old and out of date","too long to read"],"teacherNote":"Adjective: closely connected with the subject or situation (relevant to, relevant information, highly relevant). Key for summary and note-making tasks: select only relevant points. Opposite: irrelevant. The noun relevance and the opposite irrelevant are taught in the Word Family pathway. Unit 9 uses it for selecting content; Units 2 and 7 taught it in other topics."}]'::jsonb,'["relevance","irrelevant"]'::jsonb,'["relevant to","relevant information","highly relevant"]'::jsonb,'live'),
('vocab_constructive','constructive','adjective','helpful and intended to improve something, rather than just criticising it','[{"senseId":"constructive_1","meaning":"helpful and intended to improve something, rather than just criticising it","acceptedParaphrases":["helpful","useful for improving"],"masteryContexts":[{"contextId":"u9_49_constructive_meaning","text":"Good teachers give constructive criticism that helps people improve, rather than rude comments.","meaning":"helpful and intended to improve something","wrongMeanings":["unkind and intended to hurt","very short and unclear","unrelated to the work"]},{"contextId":"u9_49_constructive_paraphrase","text":"The meeting was constructive, and we agreed on three clear next steps.","meaning":"useful and producing good results","wrongMeanings":["long and boring with no results","angry and unfriendly","secret and unofficial"]}],"situationDistractors":["A boy left a rude comment under a classmate’s video.","A student wrote about football in an essay on communication.","A teacher wrote \"Bad\" on an essay without any explanation.","A boy laughed at a classmate’s drawing.","A girl left an angry comment under a video.","A teacher wrote only \"Poor\" on an essay."],"gapDistractors":[{"contextId":"u9_49_constructive_gap_1","answer":"constructive","wrong":["portable","tech-savvy","banned"]},{"contextId":"u9_49_constructive_gap_2","answer":"constructive","wrong":["portable","tech-savvy","banned"]},{"contextId":"u9_49_constructive_gap_3","answer":"constructive","wrong":["portable","tech-savvy","banned"]}],"spellingErrors":["constuctive","constructiv","contructive","constructeve","construcktive","constructivve"],"masteryPassages":[{"passageId":"u9_49_constructive_passage_1","contextId":"u9_49_constructive_gap_1","text":"Instead of just saying \"This is bad\", give ____ feedback. Explain what could be improved and how.","answer":"constructive"},{"passageId":"u9_49_constructive_passage_2","contextId":"u9_49_constructive_gap_2","text":"The meeting was very ____. Everyone listened, and the team agreed on three clear next steps.","answer":"constructive"}],"contextDependentParaphrases":[],"wrongParaphrases":["hurtful","off-topic","unclear"],"misleadingDistractors":["unkind and intended to hurt someone","not related to the topic","very short and unclear"],"teacherNote":"Adjective: helpful and intended to improve something (constructive feedback, constructive criticism, a constructive discussion). Boundary: constructive criticism points out problems and suggests improvements; negative criticism only finds fault. The verb construct is a different sense here; the adverb constructively is taught in the Word Family pathway."}]'::jsonb,'[]'::jsonb,'["constructive feedback","constructive criticism","a constructive discussion"]'::jsonb,'live'),
('vocab_research','research','noun','careful study of a subject to discover new facts or information','[{"senseId":"research_1","meaning":"careful study of a subject to discover new facts or information","acceptedParaphrases":["careful study","investigation"],"masteryContexts":[{"contextId":"u9_50_research_meaning","text":"Before writing her article, Lina did some research into how teenagers use social media.","meaning":"careful study to find information","wrongMeanings":["a quick guess without evidence","a short look at headlines","a personal opinion online"]},{"contextId":"u9_50_research_paraphrase","text":"New research suggests that video calls are more tiring than face-to-face meetings.","meaning":"scientific study that discovers new facts","wrongMeanings":["popular opinion that has not been tested","a story shared on social media","an advert for a product"]}],"situationDistractors":["A boy guessed the answer without reading the question.","A girl glanced at the news headlines on her phone.","A man posted his opinion about the film on social media.","A boy guessed the capital city without checking.","A girl scrolled quickly past a news headline.","A man shared a rumour without checking it."],"gapDistractors":[{"contextId":"u9_50_research_gap_1","answer":"research","wrong":["frustration","workforce","perception"]},{"contextId":"u9_50_research_gap_2","answer":"research","wrong":["frustration","workforce","generation"]},{"contextId":"u9_50_research_gap_3","answer":"research","wrong":["frustration","workforce","perception"]}],"spellingErrors":["reserch","reasearch","researh","resaerch","reaserch","researsh"],"masteryPassages":[{"passageId":"u9_50_research_passage_1","contextId":"u9_50_research_gap_1","text":"Before writing her article, Lina spent a week reading reports and interviewing experts. Her careful ____ made the article very convincing.","answer":"research"},{"passageId":"u9_50_research_passage_2","contextId":"u9_50_research_gap_2","text":"Scientists are carrying out ____ into how screen time affects sleep. Their early results are worrying.","answer":"research"}],"contextDependentParaphrases":[],"wrongParaphrases":["wild guess","quick glance","personal opinion"],"misleadingDistractors":["a guess made without any evidence","a quick look at the headlines","an opinion shared on social media"],"teacherNote":"Noun (uncountable): careful study to discover new facts (do/carry out research, research into/on, research shows that ...). Common error: *a research / *researches; say \"a piece of research\" or \"studies\". It can also be a verb (research a topic). The noun researcher is taught in the Word Family pathway."}]'::jsonb,'[]'::jsonb,'["carry out research","research into","research shows that"]'::jsonb,'live')
